/**
 * Size in bytes of the nonce (initialization vector) used by XChaCha20-Poly1305.
 * XChaCha20 uses a 192-bit (24-byte) nonce, providing extended nonce space compared to ChaCha20's 96-bit nonce.
 */
export const NONCE_BYTES = 24;

/**
 * Size in bytes of the authentication tag generated by Poly1305.
 * The tag is a 128-bit (16-byte) MAC (Message Authentication Code) that ensures ciphertext integrity and authenticity.
 */
export const GENERATED_TAG_BYTES = 16;

/**
 * Size in bytes of the encryption key used by XChaCha20-Poly1305.
 * The cipher requires a 256-bit (32-byte) symmetric key, derived from the secret via SHA-256.
 */
export const KEY_BYTES = 32;
